91	static status UA_FUNC_ATTR_WARN_UNUSED_RESULT
92	writeChar(CtxJson *ctx, char c) {
93	    if(ctx->pos >= ctx->end)
94	        return UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED;
95	    if(!ctx->calcOnly)
96	        *ctx->pos = (UA_Byte)c;
97	    ctx->pos++;
98	    return UA_STATUSCODE_GOOD;
99	}
