101	#define WRITE_JSON_ELEMENT(ELEM)                            \
102	    UA_FUNC_ATTR_WARN_UNUSED_RESULT status                  \
103	    writeJson##ELEM(CtxJson *ctx)
104	
105	static WRITE_JSON_ELEMENT(Quote) {
106	    return writeChar(ctx, '\"');
107	}
108	
109	WRITE_JSON_ELEMENT(ObjStart) {
110	    /* increase depth, save: before first key-value no comma needed. */
111	    ctx->depth++;
112	    ctx->commaNeeded[ctx->depth] = false;
113	    return writeChar(ctx, '{');
114	}
115	
116	WRITE_JSON_ELEMENT(ObjEnd) {
117	    ctx->depth--; //decrease depth
118	    ctx->commaNeeded[ctx->depth] = true;
119	    return writeChar(ctx, '}');
120	}
121	
122	WRITE_JSON_ELEMENT(ArrStart) {
123	    /* increase depth, save: before first array entry no comma needed. */
124	    ctx->commaNeeded[++ctx->depth] = false;
125	    return writeChar(ctx, '[');
126	}
127	
128	WRITE_JSON_ELEMENT(ArrEnd) {
129	    ctx->depth--; //decrease depth
130	    ctx->commaNeeded[ctx->depth] = true;
131	    return writeChar(ctx, ']');
132	}
133	
134	WRITE_JSON_ELEMENT(CommaIfNeeded) {
135	    if(ctx->commaNeeded[ctx->depth])
136	        return writeChar(ctx, ',');
137	    return UA_STATUSCODE_GOOD;
138	}
