154	status writeJsonNull(CtxJson *ctx) {
155	    if(ctx->pos + 4 > ctx->end)
156	        return UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED;
157	    if(ctx->calcOnly) {
158	        ctx->pos += 4;
159	    } else {
160	        *(ctx->pos++) = 'n';
161	        *(ctx->pos++) = 'u';
162	        *(ctx->pos++) = 'l';
163	        *(ctx->pos++) = 'l';
164	    }
165	    return UA_STATUSCODE_GOOD;
166	}
