241	ENCODE_JSON(Boolean) {
242	    size_t sizeOfJSONBool;
243	    if(*src == true) {
244	        sizeOfJSONBool = 4; /*"true"*/
245	    } else {
246	        sizeOfJSONBool = 5; /*"false"*/
247	    }
248	
249	    if(ctx->calcOnly) {
250	        ctx->pos += sizeOfJSONBool;
251	        return UA_STATUSCODE_GOOD;
252	    }
253	
254	    if(ctx->pos + sizeOfJSONBool > ctx->end)
255	        return UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED;
256	
257	    if(*src) {
258	        *(ctx->pos++) = 't';
259	        *(ctx->pos++) = 'r';
260	        *(ctx->pos++) = 'u';
261	        *(ctx->pos++) = 'e';
262	    } else {
263	        *(ctx->pos++) = 'f';
264	        *(ctx->pos++) = 'a';
265	        *(ctx->pos++) = 'l';
266	        *(ctx->pos++) = 's';
267	        *(ctx->pos++) = 'e';
268	    }
