648	ENCODE_JSON(ByteString) {
649	    if(!src->data)
650	        return writeJsonNull(ctx);
651	
652	    if(src->length == 0) {
653	        status retval = writeJsonQuote(ctx);
654	        retval |= writeJsonQuote(ctx);
655	        return retval;
656	    }
657	
658	    status ret = writeJsonQuote(ctx);
659	    int flen;
660	    char *ba64 = UA_base64(src->data, (int)src->length, &flen);
661	    
662	    /* Not converted, no mem */
663	    if(!ba64)
664	        return UA_STATUSCODE_BADENCODINGERROR;
665	
666	    /* Check if negative... (TODO: Why is base64 3rd argument type int?) */
667	    if(flen < 0) {
668	        UA_free(ba64);
669	        return UA_STATUSCODE_BADENCODINGERROR;
670	    }
671	
672	    if(ctx->pos + flen > ctx->end) {
673	        UA_free(ba64);
674	        return UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED;
675	    }
676	    
677	    /* Copy flen bytes to output stream. */
678	    if(!ctx->calcOnly)
679	        memcpy(ctx->pos, ba64, (size_t)flen);
680	    ctx->pos += flen;
681	
682	    /* Base64 result no longer needed */
683	    UA_free(ba64);
684	    
685	    ret |= writeJsonQuote(ctx);
686	    return ret;
687	}
