689	/* Converts Guid to a hexadecimal represenation */
690	static void UA_Guid_to_hex(const UA_Guid *guid, u8* out) {
691	    /*
692	                          16 byte
693	       +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
694	       |   data1   |data2|data3|          data4        |
695	       +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
696	       |aa aa aa aa-bb bb-cc cc-dd dd-ee ee ee ee ee ee|
697	       +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
698	                          36 character
699	    */
700	
701	#ifdef hexCharlowerCase
702	    const u8 *hexmap = hexmapLower;
703	#else
704	    const u8 *hexmap = hexmapUpper;
705	#endif
706	    size_t i = 0, j = 28;
707	    for(; i<8;i++,j-=4)         /* pos 0-7, 4byte, (a) */
708	        out[i] = hexmap[(guid->data1 >> j) & 0x0Fu];
709	    out[i++] = '-';             /* pos 8 */
710	    for(j=12; i<13;i++,j-=4)    /* pos 9-12, 2byte, (b) */
711	        out[i] = hexmap[(uint16_t)(guid->data2 >> j) & 0x0Fu];
712	    out[i++] = '-';             /* pos 13 */
713	    for(j=12; i<18;i++,j-=4)    /* pos 14-17, 2byte (c) */
714	        out[i] = hexmap[(uint16_t)(guid->data3 >> j) & 0x0Fu];
715	    out[i++] = '-';             /* pos 18 */
716	    for(j=0;i<23;i+=2,j++) {     /* pos 19-22, 2byte (d) */
717	        out[i] = hexmap[(guid->data4[j] & 0xF0u) >> 4u];
718	        out[i+1] = hexmap[guid->data4[j] & 0x0Fu];
719	    }
720	    out[i++] = '-';             /* pos 23 */
721	    for(j=2; i<36;i+=2,j++) {    /* pos 24-35, 6byte (e) */
722	        out[i] = hexmap[(guid->data4[j] & 0xF0u) >> 4u];
723	        out[i+1] = hexmap[guid->data4[j] & 0x0Fu];
724	    }
725	}
