728	ENCODE_JSON(Guid) {
729	    if(ctx->pos + 38 > ctx->end) /* 36 + 2 (") */
730	        return UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED;
731	    status ret = writeJsonQuote(ctx);
732	    u8 *buf = ctx->pos;
733	    if(!ctx->calcOnly)
734	        UA_Guid_to_hex(src, buf);
735	    ctx->pos += 36;
736	    ret |= writeJsonQuote(ctx);
737	    return ret;
738	}
