740	static void
741	printNumber(u16 n, u8 *pos, size_t digits) {
742	    for(size_t i = digits; i > 0; --i) {
743	        pos[i - 1] = (u8) ((n % 10) + '0');
744	        n = n / 10;
745	    }
746	}
