748	ENCODE_JSON(DateTime) {
749	    UA_DateTimeStruct tSt = UA_DateTime_toStruct(*src);
750	
751	    /* Format: yyyy-MM-dd'T'HH:mm:ss.SSSSSSSSS'Z' is used. max 30 bytes.*/
752	    UA_Byte buffer[UA_JSON_DATETIME_LENGTH];
753	
754	    printNumber(tSt.year, &buffer[0], 4);
755	    buffer[4] = '-';
756	    printNumber(tSt.month, &buffer[5], 2);
757	    buffer[7] = '-';
758	    printNumber(tSt.day, &buffer[8], 2);
759	    buffer[10] = 'T';
760	    printNumber(tSt.hour, &buffer[11], 2);
761	    buffer[13] = ':';
762	    printNumber(tSt.min, &buffer[14], 2);
763	    buffer[16] = ':';
764	    printNumber(tSt.sec, &buffer[17], 2);
765	    buffer[19] = '.';
766	    printNumber(tSt.milliSec, &buffer[20], 3);
767	    printNumber(tSt.microSec, &buffer[23], 3);
768	    printNumber(tSt.nanoSec, &buffer[26], 3);
769	
770	    size_t length = 28;
771	    while (buffer[length] == '0')
772	        length--;
773	    if (length != 19)
774	         length++;
775	
776	    buffer[length] = 'Z';
777	    UA_String str = {length + 1, buffer};
778	    return ENCODE_DIRECT_JSON(&str, String);
779	}
