782	static status
783	NodeId_encodeJsonInternal(UA_NodeId const *src, CtxJson *ctx) {
784	    status ret = UA_STATUSCODE_GOOD;
785	    switch (src->identifierType) {
786	    case UA_NODEIDTYPE_NUMERIC:
787	        ret |= writeJsonKey(ctx, UA_JSONKEY_ID);
788	        ret |= ENCODE_DIRECT_JSON(&src->identifier.numeric, UInt32);
789	        break;
790	    case UA_NODEIDTYPE_STRING:
791	        ret |= writeJsonKey(ctx, UA_JSONKEY_IDTYPE);
792	        ret |= writeChar(ctx, '1');
793	        ret |= writeJsonKey(ctx, UA_JSONKEY_ID);
794	        ret |= ENCODE_DIRECT_JSON(&src->identifier.string, String);
795	        break;
796	    case UA_NODEIDTYPE_GUID:
797	        ret |= writeJsonKey(ctx, UA_JSONKEY_IDTYPE);
798	        ret |= writeChar(ctx, '2');
799	        ret |= writeJsonKey(ctx, UA_JSONKEY_ID); /* Id */
800	        ret |= ENCODE_DIRECT_JSON(&src->identifier.guid, Guid);
801	        break;
802	    case UA_NODEIDTYPE_BYTESTRING:
803	        ret |= writeJsonKey(ctx, UA_JSONKEY_IDTYPE);
804	        ret |= writeChar(ctx, '3');
805	        ret |= writeJsonKey(ctx, UA_JSONKEY_ID); /* Id */
806	        ret |= ENCODE_DIRECT_JSON(&src->identifier.byteString, ByteString);
807	        break;
808	    default:
809	        return UA_STATUSCODE_BADINTERNALERROR;
810	    }
811	    return ret;
812	}
