1006	/* ExtensionObject */
1007	ENCODE_JSON(ExtensionObject) {
1008	    u8 encoding = (u8) src->encoding;
1009	    if(encoding == UA_EXTENSIONOBJECT_ENCODED_NOBODY)
1010	        return writeJsonNull(ctx);
1011	    
1012	    status ret = UA_STATUSCODE_GOOD;
1013	    /* already encoded content.*/
1014	    if(encoding <= UA_EXTENSIONOBJECT_ENCODED_XML) {
1015	        ret |= writeJsonObjStart(ctx);
1016	        if(ctx->useReversible) {
1017	            ret |= writeJsonKey(ctx, UA_JSONKEY_TYPEID);
1018	            ret |= ENCODE_DIRECT_JSON(&src->content.encoded.typeId, NodeId);
1019	            if(ret != UA_STATUSCODE_GOOD)
1020	                return ret;
1021	        }
1022	        
1023	        switch (src->encoding) {
1024	            case UA_EXTENSIONOBJECT_ENCODED_BYTESTRING:
1025	            {
1026	                if(ctx->useReversible) {
1027	                    ret |= writeJsonKey(ctx, UA_JSONKEY_ENCODING);
1028	                    ret |= writeChar(ctx, '1');
1029	                }
1030	                ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1031	                ret |= ENCODE_DIRECT_JSON(&src->content.encoded.body, String);
1032	                break;
1033	            }
1034	            case UA_EXTENSIONOBJECT_ENCODED_XML:
1035	            {
1036	                if(ctx->useReversible) {
1037	                    ret |= writeJsonKey(ctx, UA_JSONKEY_ENCODING);
1038	                    ret |= writeChar(ctx, '2');
1039	                }
1040	                ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1041	                ret |= ENCODE_DIRECT_JSON(&src->content.encoded.body, String);
1042	                break;
1043	            }
1044	            default:
1045	                ret = UA_STATUSCODE_BADINTERNALERROR;
1046	        }
1047	
1048	        ret |= writeJsonObjEnd(ctx);
1049	        return ret;
1050	    } /* encoding <= UA_EXTENSIONOBJECT_ENCODED_XML */
1051	         
1052	    /* Cannot encode with no type description */
1053	    if(!src->content.decoded.type)
1054	        return UA_STATUSCODE_BADENCODINGERROR;
1055	
1056	    if(!src->content.decoded.data)
1057	        return writeJsonNull(ctx);
1058	
1059	    UA_NodeId typeId = src->content.decoded.type->typeId;
1060	    if(typeId.identifierType != UA_NODEIDTYPE_NUMERIC)
1061	        return UA_STATUSCODE_BADENCODINGERROR;
1062	
1063	    ret |= writeJsonObjStart(ctx);
1064	    const UA_DataType *contentType = src->content.decoded.type;
1065	    if(ctx->useReversible) {
1066	        /* REVERSIBLE */
1067	        ret |= writeJsonKey(ctx, UA_JSONKEY_TYPEID);
1068	        ret |= ENCODE_DIRECT_JSON(&typeId, NodeId);
1069	
1070	        /* Encode the content */
1071	        ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1072	        ret |= encodeJsonInternal(src->content.decoded.data, contentType, ctx);
1073	    } else {
1074	        /* NON-REVERSIBLE
1075	         * For the non-reversible form, ExtensionObject values 
1076	         * shall be encoded as a JSON object containing only the 
1077	         * value of the Body field. The TypeId and Encoding fields are dropped.
1078	         * 
1079	         * TODO: UA_JSONKEY_BODY key in the ExtensionObject?
1080	         */
1081	        ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1082	        ret |= encodeJsonInternal(src->content.decoded.data, contentType, ctx);
1083	    }
1084	
1085	    ret |= writeJsonObjEnd(ctx);
1086	    return ret;
1087	}
