1089	static status
1090	Variant_encodeJsonWrapExtensionObject(const UA_Variant *src, const bool isArray, CtxJson *ctx) {
1091	    size_t length = 1;
1092	
1093	    status ret = UA_STATUSCODE_GOOD;
1094	    if(isArray) {
1095	        if(src->arrayLength > UA_INT32_MAX)
1096	            return UA_STATUSCODE_BADENCODINGERROR;
1097	        
1098	        length = src->arrayLength;
1099	    }
1100	
1101	    /* Set up the ExtensionObject */
1102	    UA_ExtensionObject eo;
1103	    UA_ExtensionObject_init(&eo);
1104	    eo.encoding = UA_EXTENSIONOBJECT_DECODED;
1105	    eo.content.decoded.type = src->type;
1106	    const u16 memSize = src->type->memSize;
1107	    uintptr_t ptr = (uintptr_t) src->data;
1108	
1109	    if(isArray) {
1110	        ret |= writeJsonArrStart(ctx);
1111	        ctx->commaNeeded[ctx->depth] = false;
1112	
1113	        /* Iterate over the array */
1114	        for(size_t i = 0; i <  length && ret == UA_STATUSCODE_GOOD; ++i) {
1115	            eo.content.decoded.data = (void*) ptr;
1116	            ret |= writeJsonArrElm(ctx, &eo, &UA_TYPES[UA_TYPES_EXTENSIONOBJECT]);
1117	            ptr += memSize;
1118	        }
1119	    
1120	        ret |= writeJsonArrEnd(ctx);
1121	        return ret;
1122	    }
1123	
1124	    eo.content.decoded.data = (void*) ptr;
1125	    return encodeJsonInternal(&eo, &UA_TYPES[UA_TYPES_EXTENSIONOBJECT], ctx);
1126	}
