1128	static status
1129	addMultiArrayContentJSON(CtxJson *ctx, void* array, const UA_DataType *type, 
1130	                         size_t *index, UA_UInt32 *arrayDimensions, size_t dimensionIndex, 
1131	                         size_t dimensionSize) {
1132	    /* Check the recursion limit */
1133	    if(ctx->depth > UA_JSON_ENCODING_MAX_RECURSION)
1134	        return UA_STATUSCODE_BADENCODINGERROR;
1135	    
1136	    /* Stop recursion: The inner Arrays are written */
1137	    status ret;
1138	    if(dimensionIndex == (dimensionSize - 1)) {
1139	        ret = encodeJsonArray(ctx, ((u8*)array) + (type->memSize * *index),
1140	                              arrayDimensions[dimensionIndex], type);
1141	        (*index) += arrayDimensions[dimensionIndex];
1142	        return ret;
1143	    }
1144	
1145	    /* Recurse to the next dimension */
1146	    ret = writeJsonArrStart(ctx);
1147	    for(size_t i = 0; i < arrayDimensions[dimensionIndex]; i++) {
1148	        ret |= writeJsonCommaIfNeeded(ctx);
1149	        ret |= addMultiArrayContentJSON(ctx, array, type, index, arrayDimensions,
1150	                                        dimensionIndex + 1, dimensionSize);
1151	        ctx->commaNeeded[ctx->depth] = true;
1152	        if(ret != UA_STATUSCODE_GOOD)
1153	            return ret;
1154	    }
1155	    ret |= writeJsonArrEnd(ctx);
1156	    return ret;
1157	}
