1159	ENCODE_JSON(Variant) {
1160	    /* If type is 0 (NULL) the Variant contains a NULL value and the containing
1161	     * JSON object shall be omitted or replaced by the JSON literal ‘null’ (when
1162	     * an element of a JSON array). */
1163	    if(!src->type) {
1164	        return writeJsonNull(ctx);
1165	    }
1166	        
1167	    /* Set the content type in the encoding mask */
1168	    const UA_Boolean isBuiltin = (src->type->typeKind <= UA_DATATYPEKIND_DIAGNOSTICINFO);
1169	    const UA_Boolean isEnum = (src->type->typeKind == UA_DATATYPEKIND_ENUM);
1170	    
1171	    /* Set the array type in the encoding mask */
1172	    const bool isArray = src->arrayLength > 0 || src->data <= UA_EMPTY_ARRAY_SENTINEL;
1173	    const bool hasDimensions = isArray && src->arrayDimensionsSize > 0;
1174	    status ret = UA_STATUSCODE_GOOD;
1175	    
1176	    if(ctx->useReversible) {
1177	        ret |= writeJsonObjStart(ctx);
1178	        if(ret != UA_STATUSCODE_GOOD)
1179	            return ret;
1180	
1181	        /* Encode the content */
1182	        if(!isBuiltin && !isEnum) {
1183	            /* REVERSIBLE:  NOT BUILTIN, can it be encoded? Wrap in extension object.*/
1184	            ret |= writeJsonKey(ctx, UA_JSONKEY_TYPE);
1185	            ret |= ENCODE_DIRECT_JSON(&UA_TYPES[UA_TYPES_EXTENSIONOBJECT].typeId.identifier.numeric, UInt32);
1186	            ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1187	            ret |= Variant_encodeJsonWrapExtensionObject(src, isArray, ctx);
1188	        } else if(!isArray) {
1189	            /*REVERSIBLE:  BUILTIN, single value.*/
1190	            ret |= writeJsonKey(ctx, UA_JSONKEY_TYPE);
1191	            ret |= ENCODE_DIRECT_JSON(&src->type->typeId.identifier.numeric, UInt32);
1192	            ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1193	            ret |= encodeJsonInternal(src->data, src->type, ctx);
1194	        } else {
1195	            /*REVERSIBLE:   BUILTIN, array.*/
1196	            ret |= writeJsonKey(ctx, UA_JSONKEY_TYPE);
1197	            ret |= ENCODE_DIRECT_JSON(&src->type->typeId.identifier.numeric, UInt32);
1198	            ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1199	            ret |= encodeJsonArray(ctx, src->data, src->arrayLength, src->type);
1200	        }
1201	        
1202	        if(ret != UA_STATUSCODE_GOOD)
1203	            return ret;
1204	        
1205	        /* REVERSIBLE:  Encode the array dimensions */
1206	        if(hasDimensions && ret == UA_STATUSCODE_GOOD) {
1207	            ret |= writeJsonKey(ctx, UA_JSONKEY_DIMENSION);
1208	            ret |= encodeJsonArray(ctx, src->arrayDimensions, src->arrayDimensionsSize, 
1209	                                   &UA_TYPES[UA_TYPES_INT32]);
1210	            if(ret != UA_STATUSCODE_GOOD)
1211	                return ret;
1212	        }
1213	
1214	        ret |= writeJsonObjEnd(ctx);
1215	        return ret;
1216	    } /* reversible */
1217	
1218	    
1219	    /* NON-REVERSIBLE
1220	     * For the non-reversible form, Variant values shall be encoded as a JSON object containing only
1221	     * the value of the Body field. The Type and Dimensions fields are dropped. Multi-dimensional
1222	     * arrays are encoded as a multi dimensional JSON array as described in 5.4.5.
1223	     */
1224	
1225	    ret |= writeJsonObjStart(ctx);
1226	    if(!isBuiltin && !isEnum) {
1227	        /*NON REVERSIBLE:  NOT BUILTIN, can it be encoded? Wrap in extension object.*/
1228	        if(src->arrayDimensionsSize > 1) {
1229	            return UA_STATUSCODE_BADNOTIMPLEMENTED;
1230	        }
1231	
1232	        ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1233	        ret |= Variant_encodeJsonWrapExtensionObject(src, isArray, ctx);
1234	    } else if(!isArray) {
1235	        /*NON REVERSIBLE:   BUILTIN, single value.*/
1236	        ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1237	        ret |= encodeJsonInternal(src->data, src->type, ctx);
1238	    } else {
1239	        /*NON REVERSIBLE:   BUILTIN, array.*/
1240	        ret |= writeJsonKey(ctx, UA_JSONKEY_BODY);
1241	
1242	        size_t dimensionSize = src->arrayDimensionsSize;
1243	        if(dimensionSize > 1) {
1244	            /*nonreversible multidimensional array*/
1245	            size_t index = 0;  size_t dimensionIndex = 0;
1246	            void *ptr = src->data;
1247	            const UA_DataType *arraytype = src->type;
1248	            ret |= addMultiArrayContentJSON(ctx, ptr, arraytype, &index, 
1249	                    src->arrayDimensions, dimensionIndex, dimensionSize);
1250	        } else {
1251	            /*nonreversible simple array*/
1252	            ret |= encodeJsonArray(ctx, src->data, src->arrayLength, src->type);
1253	        }
1254	    }
1255	
1256	    ret |= writeJsonObjEnd(ctx);
1257	    return ret;
1258	}
1259	
1260	/* DataValue */
1261	ENCODE_JSON(DataValue) {
1262	    UA_Boolean hasValue = src->hasValue && src->value.type != NULL;
1263	    UA_Boolean hasStatus = src->hasStatus && src->status;
1264	    UA_Boolean hasSourceTimestamp = src->hasSourceTimestamp && src->sourceTimestamp;
1265	    UA_Boolean hasSourcePicoseconds = src->hasSourcePicoseconds && src->sourcePicoseconds;
1266	    UA_Boolean hasServerTimestamp = src->hasServerTimestamp && src->serverTimestamp;
1267	    UA_Boolean hasServerPicoseconds = src->hasServerPicoseconds && src->serverPicoseconds;
1268	
1269	    if(!hasValue && !hasStatus && !hasSourceTimestamp && !hasSourcePicoseconds &&
1270	       !hasServerTimestamp && !hasServerPicoseconds) {
1271	        return writeJsonNull(ctx); /*no element, encode as null*/
1272	    }
1273	
1274	    status ret = UA_STATUSCODE_GOOD;
1275	    ret |= writeJsonObjStart(ctx);
1276	
1277	    if(hasValue) {
1278	        ret |= writeJsonKey(ctx, UA_JSONKEY_VALUE);
1279	        ret |= ENCODE_DIRECT_JSON(&src->value, Variant);
1280	        if(ret != UA_STATUSCODE_GOOD)
1281	            return ret;
1282	    }
1283	
1284	    if(hasStatus) {
1285	        ret |= writeJsonKey(ctx, UA_JSONKEY_STATUS);
1286	        ret |= ENCODE_DIRECT_JSON(&src->status, StatusCode);
1287	        if(ret != UA_STATUSCODE_GOOD)
1288	            return ret;
1289	    }
1290	
1291	    if(hasSourceTimestamp) {
1292	        ret |= writeJsonKey(ctx, UA_JSONKEY_SOURCETIMESTAMP);
1293	        ret |= ENCODE_DIRECT_JSON(&src->sourceTimestamp, DateTime);
1294	        if(ret != UA_STATUSCODE_GOOD)
1295	            return ret;
1296	    }
1297	
1298	    if(hasSourcePicoseconds) {
1299	        ret |= writeJsonKey(ctx, UA_JSONKEY_SOURCEPICOSECONDS);
1300	        ret |= ENCODE_DIRECT_JSON(&src->sourcePicoseconds, UInt16);
1301	        if(ret != UA_STATUSCODE_GOOD)
1302	            return ret;
1303	    }
1304	
1305	    if(hasServerTimestamp) {
1306	        ret |= writeJsonKey(ctx, UA_JSONKEY_SERVERTIMESTAMP);
1307	        ret |= ENCODE_DIRECT_JSON(&src->serverTimestamp, DateTime);
1308	        if(ret != UA_STATUSCODE_GOOD)
1309	            return ret;
1310	    }
1311	
1312	    if(hasServerPicoseconds) {
1313	        ret |= writeJsonKey(ctx, UA_JSONKEY_SERVERPICOSECONDS);
1314	        ret |= ENCODE_DIRECT_JSON(&src->serverPicoseconds, UInt16);
1315	        if(ret != UA_STATUSCODE_GOOD)
1316	            return ret;
1317	    }
1318	
1319	    ret |= writeJsonObjEnd(ctx);
1320	    return ret;
1321	}
