1323	/* DiagnosticInfo */
1324	ENCODE_JSON(DiagnosticInfo) {
1325	    status ret = UA_STATUSCODE_GOOD;
1326	    if(!src->hasSymbolicId && !src->hasNamespaceUri && !src->hasLocalizedText &&
1327	       !src->hasLocale && !src->hasAdditionalInfo && !src->hasInnerDiagnosticInfo &&
1328	       !src->hasInnerStatusCode) {
1329	        return writeJsonNull(ctx); /*no element present, encode as null.*/
1330	    }
1331	    
1332	    ret |= writeJsonObjStart(ctx);
1333	    
1334	    if(src->hasSymbolicId) {
1335	        ret |= writeJsonKey(ctx, UA_JSONKEY_SYMBOLICID);
1336	        ret |= ENCODE_DIRECT_JSON(&src->symbolicId, UInt32);
1337	        if(ret != UA_STATUSCODE_GOOD)
1338	            return ret;
1339	    }
1340	
1341	    if(src->hasNamespaceUri) {
1342	        ret |= writeJsonKey(ctx, UA_JSONKEY_NAMESPACEURI);
1343	        ret |= ENCODE_DIRECT_JSON(&src->namespaceUri, UInt32);
1344	        if(ret != UA_STATUSCODE_GOOD)
1345	            return ret;
1346	    }
1347	    
1348	    if(src->hasLocalizedText) {
1349	        ret |= writeJsonKey(ctx, UA_JSONKEY_LOCALIZEDTEXT);
1350	        ret |= ENCODE_DIRECT_JSON(&src->localizedText, UInt32);
1351	        if(ret != UA_STATUSCODE_GOOD)
1352	            return ret;
1353	    }
1354	    
1355	    if(src->hasLocale) {
1356	        ret |= writeJsonKey(ctx, UA_JSONKEY_LOCALE);
1357	        ret |= ENCODE_DIRECT_JSON(&src->locale, UInt32);
1358	        if(ret != UA_STATUSCODE_GOOD)
1359	            return ret;
1360	    }
1361	    
1362	    if(src->hasAdditionalInfo) {
1363	        ret |= writeJsonKey(ctx, UA_JSONKEY_ADDITIONALINFO);
1364	        ret |= ENCODE_DIRECT_JSON(&src->additionalInfo, String);
1365	        if(ret != UA_STATUSCODE_GOOD)
1366	            return ret;
1367	    }
1368	
1369	    if(src->hasInnerStatusCode) {
1370	        ret |= writeJsonKey(ctx, UA_JSONKEY_INNERSTATUSCODE);
1371	        ret |= ENCODE_DIRECT_JSON(&src->innerStatusCode, StatusCode);
1372	        if(ret != UA_STATUSCODE_GOOD)
1373	            return ret;
1374	    }
1375	
1376	    if(src->hasInnerDiagnosticInfo && src->innerDiagnosticInfo) {
1377	        ret |= writeJsonKey(ctx, UA_JSONKEY_INNERDIAGNOSTICINFO);
1378	        /* Check recursion depth in encodeJsonInternal */
1379	        ret |= encodeJsonInternal(src->innerDiagnosticInfo, &UA_TYPES[UA_TYPES_DIAGNOSTICINFO], ctx);
1380	        if(ret != UA_STATUSCODE_GOOD)
1381	            return ret;
1382	    }
1383	
1384	    ret |= writeJsonObjEnd(ctx);
