1388	static status
1389	encodeJsonStructure(const void *src, const UA_DataType *type, CtxJson *ctx) {
1390	    /* Check the recursion limit */
1391	    if(ctx->depth > UA_JSON_ENCODING_MAX_RECURSION)
1392	        return UA_STATUSCODE_BADENCODINGERROR;
1393	    ctx->depth++;
1394	
1395	    status ret = writeJsonObjStart(ctx);
1396	
1397	    uintptr_t ptr = (uintptr_t) src;
1398	    u8 membersSize = type->membersSize;
1399	    const UA_DataType * typelists[2] = {UA_TYPES, &type[-type->typeIndex]};
1400	    for(size_t i = 0; i < membersSize && ret == UA_STATUSCODE_GOOD; ++i) {
1401	        const UA_DataTypeMember *m = &type->members[i];
1402	        const UA_DataType *mt = &typelists[!m->namespaceZero][m->memberTypeIndex];
1403	
1404	        if(m->memberName != NULL && *m->memberName != 0)
1405	            ret |= writeJsonKey(ctx, m->memberName);
1406	
1407	        if(!m->isArray) {
1408	            ptr += m->padding;
1409	            size_t memSize = mt->memSize;
1410	            ret |= encodeJsonJumpTable[mt->typeKind]((const void*) ptr, mt, ctx);
1411	            ptr += memSize;
1412	        } else {
1413	            ptr += m->padding;
1414	            const size_t length = *((const size_t*) ptr);
1415	            ptr += sizeof (size_t);
1416	            ret |= encodeJsonArray(ctx, *(void * const *)ptr, length, mt);
1417	            ptr += sizeof (void*);
1418	        }
1419	    }
1420	
1421	    ret |= writeJsonObjEnd(ctx);
1422	
1423	    ctx->depth--;
1424	    return ret;
1425	}
