1472	status UA_FUNC_ATTR_WARN_UNUSED_RESULT
1473	UA_encodeJson(const void *src, const UA_DataType *type,
1474	              u8 **bufPos, const u8 **bufEnd, UA_String *namespaces, 
1475	              size_t namespaceSize, UA_String *serverUris, 
1476	              size_t serverUriSize, UA_Boolean useReversible) {
1477	    if(!src || !type)
1478	        return UA_STATUSCODE_BADINTERNALERROR;
1479	    
1480	    /* Set up the context */
1481	    CtxJson ctx;
1482	    memset(&ctx, 0, sizeof(ctx));
1483	    ctx.pos = *bufPos;
1484	    ctx.end = *bufEnd;
1485	    ctx.depth = 0;
1486	    ctx.namespaces = namespaces;
1487	    ctx.namespacesSize = namespaceSize;
1488	    ctx.serverUris = serverUris;
1489	    ctx.serverUrisSize = serverUriSize;
1490	    ctx.useReversible = useReversible;
1491	    ctx.calcOnly = false;
1492	    
1493	    /* Encode */
1494	    status ret = encodeJsonJumpTable[type->typeKind](src, type, &ctx);
1495	    
1496	    *bufPos = ctx.pos;
1497	    *bufEnd = ctx.end;
1498	    return ret;
