1536	/* Macro which gets current size and char pointer of current Token. Needs
1537	 * ParseCtx (parseCtx) and CtxJson (ctx). Does NOT increment index of Token. */
1538	#define GET_TOKEN(data, size) do {                                               \
1539	    (size) = (size_t)(parseCtx->tokenArray[parseCtx->index].end - parseCtx->tokenArray[parseCtx->index].start); \
1540	    (data) = (char*)(ctx->pos + parseCtx->tokenArray[parseCtx->index].start); } while(0)
1541	
1542	#define ALLOW_NULL do {             \
1543	    if(isJsonNull(ctx, parseCtx)) { \
1544	        parseCtx->index++;          \
1545	        return UA_STATUSCODE_GOOD;  \
1546	    }} while(0)
1547	
1548	#define CHECK_TOKEN_BOUNDS do {                   \
1549	    if(parseCtx->index >= parseCtx->tokenCount)   \
1550	        return UA_STATUSCODE_BADDECODINGERROR;    \
1551	    } while(0)
1552	
1553	#define CHECK_PRIMITIVE do {                      \
1554	    if(getJsmnType(parseCtx) != JSMN_PRIMITIVE) { \
1555	        return UA_STATUSCODE_BADDECODINGERROR;    \
1556	    }} while(0)
1557	
1558	#define CHECK_STRING do {                      \
1559	    if(getJsmnType(parseCtx) != JSMN_STRING) { \
1560	        return UA_STATUSCODE_BADDECODINGERROR; \
1561	    }} while(0)
1562	
1563	#define CHECK_OBJECT do {                      \
1564	    if(getJsmnType(parseCtx) != JSMN_OBJECT) { \
1565	        return UA_STATUSCODE_BADDECODINGERROR; \
1566	    }} while(0)
