1596	static UA_Boolean
1597	isJsonTokenNull(const CtxJson *ctx, jsmntok_t *token) {
1598	    if(token->type != JSMN_PRIMITIVE)
1599	        return false;
1600	    char* elem = (char*)(ctx->pos + token->start);
1601	    return (elem[0] == 'n' && elem[1] == 'u' && elem[2] == 'l' && elem[3] == 'l');
1602	}
