1607	        return false;
1608	
1609	    if(parseCtx->tokenArray[parseCtx->index].type != JSMN_PRIMITIVE) {
1610	        return false;
1611	    }
1612	    char* elem = (char*)(ctx->pos + parseCtx->tokenArray[parseCtx->index].start);
1613	    return (elem[0] == 'n' && elem[1] == 'u' && elem[2] == 'l' && elem[3] == 'l');
