1616	static UA_SByte jsoneq(const char *json, jsmntok_t *tok, const char *searchKey) {
1617	    /* TODO: necessary?
1618	       if(json == NULL
1619	            || tok == NULL 
1620	            || searchKey == NULL) {
1621	        return -1;
1622	    } */
1623	    
1624	    if(tok->type == JSMN_STRING) {
1625	         if(strlen(searchKey) == (size_t)(tok->end - tok->start) ) {
1626	             if(strncmp(json + tok->start,
1627	                        (const char*)searchKey, (size_t)(tok->end - tok->start)) == 0) {
