1635	DECODE_JSON(Boolean) {
1636	    CHECK_PRIMITIVE;
1637	    CHECK_TOKEN_BOUNDS;
1638	    size_t tokenSize;
1639	    char* tokenData;
1640	    GET_TOKEN(tokenData, tokenSize);
1641	
1642	    if(tokenSize == 4 &&
1643	       tokenData[0] == 't' && tokenData[1] == 'r' &&
1644	       tokenData[2] == 'u' && tokenData[3] == 'e') {
1645	        *dst = true;
1646	    } else if(tokenSize == 5 &&
1647	              tokenData[0] == 'f' && tokenData[1] == 'a' &&
1648	              tokenData[2] == 'l' && tokenData[3] == 's' &&
1649	              tokenData[4] == 'e') {
1650	        *dst = false;
1651	    } else {
1652	        return UA_STATUSCODE_BADDECODINGERROR;
1653	    }
1654	    
1655	    if(moveToken)
1656	        parseCtx->index++;
1657	    return UA_STATUSCODE_GOOD;
1658	}
