1683	/* Safe strtol variant of unsigned string conversion.
1684	 * Returns UA_STATUSCODE_BADDECODINGERROR in case of overflows.
1685	 * Buffer limit is 20 digits. */
1686	static UA_StatusCode
1687	parseUnsignedInteger(char* inputBuffer, size_t sizeOfBuffer,
1688	                     UA_UInt64 *destinationOfNumber) {
1689	    /* Check size to avoid huge malicious stack allocation.
1690	     * No UInt64 can have more digits than 20. */
