1887	static UA_UInt32 hex2int(char ch) {
1888	    if(ch >= '0' && ch <= '9')
1889	        return (UA_UInt32)(ch - '0');
1890	    if(ch >= 'A' && ch <= 'F')
1891	        return (UA_UInt32)(ch - 'A' + 10);
1892	    if(ch >= 'a' && ch <= 'f')
1893	        return (UA_UInt32)(ch - 'a' + 10);
1894	    return 0;
