1932	            *dst = (UA_Float)NAN;
1933	            return UA_STATUSCODE_GOOD;
1934	        }
1935	        return UA_STATUSCODE_BADDECODINGERROR;
1936	    }
1937	    
1938	    if(tokenType != JSMN_PRIMITIVE)
1939	        return UA_STATUSCODE_BADDECODINGERROR;
1940	
1941	    /* Null-Terminate for sscanf. */
1942	    UA_STACKARRAY(char, string, tokenSize+1);
1943	    memcpy(string, tokenData, tokenSize);
1944	    string[tokenSize] = 0;
1945	    
1946	    UA_Float d = 0;
1947	#ifdef UA_ENABLE_CUSTOM_LIBC
1948	    d = (UA_Float)__floatscan(string, 1, 0);
1949	#else
1950	    char c = 0;
1951	    /* On success, the function returns the number of variables filled.
