2037	/*
2038	  Expects 36 chars in format    00000003-0009-000A-0807-060504030201
2039	                                | data1| |d2| |d3| |d4| |  data4   |
2040	*/
2041	static UA_Guid UA_Guid_fromChars(const char* chars) {
2042	    UA_Guid dst;
2043	    UA_Guid_init(&dst);
2044	    for(size_t i = 0; i < 8; i++)
2045	        dst.data1 |= (UA_UInt32)(hex2int(chars[i]) << (28 - (i*4)));
2046	    for(size_t i = 0; i < 4; i++) {
2047	        dst.data2 |= (UA_UInt16)(hex2int(chars[9+i]) << (12 - (i*4)));
2048	        dst.data3 |= (UA_UInt16)(hex2int(chars[14+i]) << (12 - (i*4)));
2049	    }
2050	    dst.data4[0] |= (UA_Byte)(hex2int(chars[19]) << 4u);
2051	    dst.data4[0] |= (UA_Byte)(hex2int(chars[20]) << 0u);
2052	    dst.data4[1] |= (UA_Byte)(hex2int(chars[21]) << 4u);
2053	    dst.data4[1] |= (UA_Byte)(hex2int(chars[22]) << 0u);
2054	    for(size_t i = 0; i < 6; i++) {
2055	        dst.data4[2+i] |= (UA_Byte)(hex2int(chars[24 + i*2]) << 4u);
2056	        dst.data4[2+i] |= (UA_Byte)(hex2int(chars[25 + i*2]) << 0u);
2057	    }
2058	    return dst;
2059	}
