2088	DECODE_JSON(String) {
2089	    ALLOW_NULL;
2090	    CHECK_STRING;
2091	    CHECK_TOKEN_BOUNDS;
2092	    size_t tokenSize;
2093	    char* tokenData;
2094	    GET_TOKEN(tokenData, tokenSize);
2095	
2096	    /* Empty string? */
2097	    if(tokenSize == 0) {
2098	        dst->data = (UA_Byte*)UA_EMPTY_ARRAY_SENTINEL;
2099	        dst->length = 0;
2100	        if(moveToken)
2101	            parseCtx->index++;
2102	        return UA_STATUSCODE_GOOD;
2103	    }
2104	    
2105	    /* The actual value is at most of the same length as the source string:
2106	     * - Shortcut escapes (e.g. "\t") (length 2) are converted to 1 byte
2107	     * - A single \uXXXX escape (length 6) is converted to at most 3 bytes
2108	     * - Two \uXXXX escapes (length 12) forming an UTF-16 surrogate pair are
2109	     *   converted to 4 bytes */
2110	    char *outputBuffer = (char*)UA_malloc(tokenSize);
2111	    if(!outputBuffer)
2112	        return UA_STATUSCODE_BADOUTOFMEMORY;
2113	    
2114	    const char *p = (char*)tokenData;
2115	    const char *end = (char*)&tokenData[tokenSize];
2116	    char *pos = outputBuffer;
2117	    while(p < end) {
2118	        /* No escaping */
2119	        if(*p != '\\') {
2120	            *(pos++) = *(p++);
2121	            continue;
2122	        }
2123	
2124	        /* Escape character */
2125	        p++;
2126	        if(p == end)
2127	            goto cleanup;
2128	        
2129	        if(*p != 'u') {
2130	            switch(*p) {
2131	            case '"': case '\\': case '/': *pos = *p; break;
2132	            case 'b': *pos = '\b'; break;
2133	            case 'f': *pos = '\f'; break;
2134	            case 'n': *pos = '\n'; break;
2135	            case 'r': *pos = '\r'; break;
2136	            case 't': *pos = '\t'; break;
2137	            default: goto cleanup;
2138	            }
2139	            pos++;
2140	            p++;
2141	            continue;
2142	        }
2143	            
2144	        /* Unicode */
2145	        if(p + 4 >= end)
2146	            goto cleanup;
2147	        int32_t value_signed = decode_unicode_escape(p);
2148	        if(value_signed < 0)
2149	            goto cleanup;
2150	        uint32_t value = (uint32_t)value_signed;
2151	        p += 5;
2152	
2153	        if(0xD800 <= value && value <= 0xDBFF) {
2154	            /* Surrogate pair */
2155	            if(p + 5 >= end)
2156	                goto cleanup;
2157	            if(*p != '\\' || *(p + 1) != 'u')
2158	                goto cleanup;
2159	            int32_t value2 = decode_unicode_escape(p + 1);
2160	            if(value2 < 0xDC00 || value2 > 0xDFFF)
2161	                goto cleanup;
2162	            value = ((value - 0xD800u) << 10u) + (uint32_t)((value2 - 0xDC00) + 0x10000);
2163	            p += 6;
2164	        } else if(0xDC00 <= value && value <= 0xDFFF) {
2165	            /* Invalid Unicode '\\u%04X' */
2166	            goto cleanup;
2167	        }
2168	
2169	        size_t length;
2170	        if(utf8_encode((int32_t)value, pos, &length))
2171	            goto cleanup;
2172	
2173	        pos += length;
2174	    }
2175	
2176	    dst->length = (size_t)(pos - outputBuffer);
2177	    if(dst->length > 0) {
2178	        dst->data = (UA_Byte*)outputBuffer;
2179	    } else {
2180	        dst->data = (UA_Byte*)UA_EMPTY_ARRAY_SENTINEL;
2181	        UA_free(outputBuffer);
2182	    }
2183	
2184	    if(moveToken)
2185	        parseCtx->index++;
2186	    return UA_STATUSCODE_GOOD;
2187	    
2188	cleanup:
2189	    UA_free(outputBuffer);  
2190	    return UA_STATUSCODE_BADDECODINGERROR;
2191	}
