2245	/* Function for searching ahead of the current token. Used for retrieving the
2246	 * OPC UA type of a token */
2247	static status
2248	searchObjectForKeyRec(const char *searchKey, CtxJson *ctx, 
2249	                      ParseCtx *parseCtx, size_t *resultIndex, UA_UInt16 depth) {
2250	    UA_StatusCode ret = UA_STATUSCODE_BADNOTFOUND;
2251	    
2252	    CHECK_TOKEN_BOUNDS;
2253	    
2254	    if(parseCtx->tokenArray[parseCtx->index].type == JSMN_OBJECT) {
2255	        size_t objectCount = (size_t)(parseCtx->tokenArray[parseCtx->index].size);
2256	        
2257	        parseCtx->index++; /*Object to first Key*/
2258	        CHECK_TOKEN_BOUNDS;
2259	        
2260	        size_t i;
2261	        for(i = 0; i < objectCount; i++) {
2262	            
2263	            CHECK_TOKEN_BOUNDS;
2264	            if(depth == 0) { /* we search only on first layer */
2265	                if(jsoneq((char*)ctx->pos, &parseCtx->tokenArray[parseCtx->index], searchKey) == 0) {
2266	                    /*found*/
2267	                    parseCtx->index++; /*We give back a pointer to the value of the searched key!*/
2268	                    *resultIndex = parseCtx->index;
2269	                    ret = UA_STATUSCODE_GOOD;
2270	                    break;
2271	                }
2272	            }
2273	               
2274	            parseCtx->index++; /* value */
2275	            CHECK_TOKEN_BOUNDS;
2276	            
2277	            if(parseCtx->tokenArray[parseCtx->index].type == JSMN_OBJECT) {
2278	               ret = searchObjectForKeyRec(searchKey, ctx, parseCtx, resultIndex,
2279	                                           (UA_UInt16)(depth + 1));
2280	            } else if(parseCtx->tokenArray[parseCtx->index].type == JSMN_ARRAY) {
