2546	DECODE_JSON(DateTime) {
2547	    CHECK_STRING;
2548	    CHECK_TOKEN_BOUNDS;
2549	    size_t tokenSize;
2550	    char* tokenData;
2551	    GET_TOKEN(tokenData, tokenSize);
2552	    
2553	    /* TODO: proper ISO 8601:2004 parsing, musl strptime!*/
2554	    /* DateTime  ISO 8601:2004 without milli is 20 Characters, with millis 24 */
2555	    if(tokenSize != 20 && tokenSize != 24) {
2556	        return UA_STATUSCODE_BADDECODINGERROR;
2557	    }
2558	    
2559	    /* sanity check */
2560	    if(tokenData[4] != '-' || tokenData[7] != '-' || tokenData[10] != 'T' ||
2561	       tokenData[13] != ':' || tokenData[16] != ':' ||
2562	       !(tokenData[19] == 'Z' || tokenData[19] == '.')) {
2563	        return UA_STATUSCODE_BADDECODINGERROR;
2564	    }
2565	    
2566	    struct mytm dts;
2567	    memset(&dts, 0, sizeof(dts));
2568	    
2569	    UA_UInt64 year = 0;
2570	    atoiUnsigned(&tokenData[0], 4, &year);
2571	    dts.tm_year = (UA_UInt16)year - 1900;
2572	    UA_UInt64 month = 0;
2573	    atoiUnsigned(&tokenData[5], 2, &month);
2574	    dts.tm_mon = (UA_UInt16)month - 1;
2575	    UA_UInt64 day = 0;
2576	    atoiUnsigned(&tokenData[8], 2, &day);
2577	    dts.tm_mday = (UA_UInt16)day;
2578	    UA_UInt64 hour = 0;
2579	    atoiUnsigned(&tokenData[11], 2, &hour);
2580	    dts.tm_hour = (UA_UInt16)hour;
2581	    UA_UInt64 min = 0;
2582	    atoiUnsigned(&tokenData[14], 2, &min);
2583	    dts.tm_min = (UA_UInt16)min;
2584	    UA_UInt64 sec = 0;
2585	    atoiUnsigned(&tokenData[17], 2, &sec);
2586	    dts.tm_sec = (UA_UInt16)sec;
2587	    
2588	    UA_UInt64 msec = 0;
2589	    if(tokenSize == 24) {
2590	        atoiUnsigned(&tokenData[20], 3, &msec);
2591	    }
2592	    
2593	    long long sinceunix = __tm_to_secs(&dts);
2594	    UA_DateTime dt = (UA_DateTime)((UA_UInt64)(sinceunix*UA_DATETIME_SEC +
2595	                                               UA_DATETIME_UNIX_EPOCH) +
2596	                                   (UA_UInt64)(UA_DATETIME_MSEC * msec)); 
2597	    *dst = dt;
2598	  
2599	    if(moveToken)
2600	        parseCtx->index++;
