2624	    CHECK_OBJECT;
2625	
2626	    /* First search for the variant type in the json object. */
2627	    size_t searchResultType = 0;
2628	    status ret = lookAheadForKey(UA_JSONKEY_TYPE, ctx, parseCtx, &searchResultType);
2629	    if(ret != UA_STATUSCODE_GOOD)
2630	        return UA_STATUSCODE_BADDECODINGERROR;
2631	
2632	    size_t size = (size_t)(parseCtx->tokenArray[searchResultType].end - parseCtx->tokenArray[searchResultType].start);
2633	
2634	    /* check if size is zero or the type is not a number */
2635	    if(size < 1 || parseCtx->tokenArray[searchResultType].type != JSMN_PRIMITIVE) {
2636	        return UA_STATUSCODE_BADDECODINGERROR;
2637	    }
2638	    
2639	    /*Parse the type*/
2640	    UA_UInt64 idTypeDecoded = 0;
2641	    char *idTypeEncoded = (char*)(ctx->pos + parseCtx->tokenArray[searchResultType].start);
2642	    status typeDecodeStatus = atoiUnsigned(idTypeEncoded, size, &idTypeDecoded);
2643	    
2644	    /* value is not a valid number */
2645	    if(typeDecodeStatus != UA_STATUSCODE_GOOD) {
2646	        return typeDecodeStatus;
2647	    }
2648	
2649	    /*Set the type, Get the Type by nodeID!*/
2650	    UA_NodeId typeNodeId = UA_NODEID_NUMERIC(0, (UA_UInt32)idTypeDecoded);
2651	    const UA_DataType *bodyType = UA_findDataType(&typeNodeId);
2652	    if(bodyType == NULL) {
2653	        return UA_STATUSCODE_BADDECODINGERROR;
2654	    }
2655	    
2656	    /*Set the type*/
2657	    dst->type = bodyType;
2658	    
2659	    /* LookAhead BODY */
2660	    /* Does the variant contain an array? */
2661	    UA_Boolean isArray = false;
2662	    UA_Boolean isBodyNull = false;
2663	    
2664	    /* Search for body */
2665	    size_t searchResultBody = 0;
2666	    ret = lookAheadForKey(UA_JSONKEY_BODY, ctx, parseCtx, &searchResultBody);
2667	    if(ret == UA_STATUSCODE_GOOD) { /* body found */
2668	        /* get body token */
2669	        jsmntok_t bodyToken = parseCtx->tokenArray[searchResultBody];
2670	        
2671	        /*BODY is null?*/
2672	        if(isJsonTokenNull(ctx, &bodyToken)) {
2673	            dst->data = NULL;
2674	            isBodyNull = true;
2675	        }
2676	        
2677	        if(bodyToken.type == JSMN_ARRAY) {
2678	            isArray = true;
2679	            
2680	            size_t arraySize = 0;
2681	            arraySize = (size_t)parseCtx->tokenArray[searchResultBody].size;
2682	            dst->arrayLength = arraySize;
2683	        }
2684	    } else {
2685	        /*TODO: no body? set value NULL?*/
2686	        return UA_STATUSCODE_BADDECODINGERROR;
2687	    }
2688	    
2689	    /* LookAhead DIMENSION */
2690	    UA_Boolean hasDimension = false;
2691	
2692	    /* Has the variant dimension? */
2693	    size_t searchResultDim = 0;
2694	    ret = lookAheadForKey(UA_JSONKEY_DIMENSION, ctx, parseCtx, &searchResultDim);
2695	    if(ret == UA_STATUSCODE_GOOD) {
2696	        hasDimension = true;
2697	        size_t dimensionSize = 0;
2698	        dimensionSize = (size_t)parseCtx->tokenArray[searchResultDim].size;
2699	        dst->arrayDimensionsSize = dimensionSize;
2700	    }
2701	    
2702	    /* no array but has dimension. error? */
2703	    if(!isArray && hasDimension)
2704	        return UA_STATUSCODE_BADDECODINGERROR;
2705	    
2706	    /* Get the datatype of the content. The type must be a builtin data type.
2707	    * All not-builtin types are wrapped in an ExtensionObject. */
2708	    if(bodyType->typeKind > UA_TYPES_DIAGNOSTICINFO)
2709	        return UA_STATUSCODE_BADDECODINGERROR;
