2716	    if(isArray) {
2717	        DecodeEntry entries[3] = {
2718	            {UA_JSONKEY_TYPE, NULL, NULL, false, NULL},
2719	            {UA_JSONKEY_BODY, &dst->data, (decodeJsonSignature) Array_decodeJson, false, NULL},
2720	            {UA_JSONKEY_DIMENSION, &dst->arrayDimensions,
2721	             (decodeJsonSignature) VariantDimension_decodeJson, false, NULL}};
2722	
2723	        if(!hasDimension) {
2724	            ret = decodeFields(ctx, parseCtx, entries, 2, bodyType); /*use first 2 fields*/
2725	        } else {
2726	            ret = decodeFields(ctx, parseCtx, entries, 3, bodyType); /*use all fields*/
2727	        }      
2728	    } else if(bodyType->typeKind != UA_DATATYPEKIND_EXTENSIONOBJECT) {
2729	        /* Allocate Memory for Body */
