3118	static status
3119	Array_decodeJson_internal(void **dst, const UA_DataType *type, 
3120	        CtxJson *ctx, ParseCtx *parseCtx, UA_Boolean moveToken) {
3121	    (void) moveToken;
3122	    status ret;
3123	    
3124	    if(parseCtx->tokenArray[parseCtx->index].type != JSMN_ARRAY)
3125	        return UA_STATUSCODE_BADDECODINGERROR;
3126	    
3127	    size_t length = (size_t)parseCtx->tokenArray[parseCtx->index].size;
3128	
3129	    /* Save the length of the array */
3130	    size_t *p = (size_t*) dst - 1;
3131	    *p = length;
3132	
3133	    /* Return early for empty arrays */
3134	    if(length == 0) {
3135	        *dst = UA_EMPTY_ARRAY_SENTINEL;
3136	        return UA_STATUSCODE_GOOD;
3137	    }
3138	
3139	    /* Allocate memory */
3140	    *dst = UA_calloc(length, type->memSize);
3141	    if(*dst == NULL)
3142	        return UA_STATUSCODE_BADOUTOFMEMORY;
3143	    
3144	    parseCtx->index++; /* We go to first Array member!*/
3145	    
3146	    /* Decode array members */
3147	    uintptr_t ptr = (uintptr_t)*dst;
